window.SUBJECTS.push({"id":"static","n":"Static GK","tab":"Static GK","w":"Dances, music, festivals, monuments, books, sports, awards and firsts.","topics":[{"id":"dance","n":"Dances","qs":[{"id":"q0040","q":"Guru Bipin Singh was a legend in the field of which classical dance?","o":["Kuchipudi","Odissi","Manipuri","Bharatnatyam"],"a":2,"x":"Guru Bipin Singh (1918–2000) is called the father of modern Manipuri dance; he received the Kalidas Samman.","e":"Manipuri's best-known forms: Ras Lila, and the Pung Cholom drum dance.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0077","q":"Mallika Sarabhai is a noted exponent of which two Indian classical dance forms?","o":["Mohiniyattam and Sattriya","Kuchipudi and Bharatnatyam","Manipuri and Kathakali","Kathak and Odissi"],"a":1,"x":"Mallika Sarabhai is a noted exponent of Kuchipudi and Bharatanatyam and runs the Darpana Academy in Ahmedabad, founded by her mother Mrinalini Sarabhai.","e":"Kuchipudi comes from Andhra Pradesh; Bharatanatyam from Tamil Nadu.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0161","q":"Who among the following distinguished individuals has been bestowed with the Kalidas Samman, a prestigious award instituted by the Madhya Pradesh Government in 2006, because of exceptional contributions to Indian dance forms such as Kathak and Bharatanatyam in 2006, apart from many other awards like the Padma Bhushan (1992) and the Padma Vibhushan (2003)?","o":["Sonal Mansingh","Birju Maharaj","Mallika Sarabhai","Malavika Sarukkai"],"a":0,"x":"Sonal Mansingh, a leading Odissi and Bharatanatyam dancer, received the Padma Bhushan (1992), the Padma Vibhushan (2003) and Madhya Pradesh's Kalidas Samman.","e":"She was nominated to the Rajya Sabha in 2018.","src":["ASO 19 Aug 2025 S3"],"k":"The question says Kathak and Bharatanatyam; she is best known for Odissi and Bharatanatyam. DSSSB's answer, Sonal Mansingh, still stands."},{"id":"q0337","q":"Who among the following founded the Darpana Academy of Performing Arts in 1949?","o":["Mrinalini Sarabhai","Mallika Sarabhai","Rukmani Arundale","Birju Maharaj"],"a":0,"x":"Mrinalini Sarabhai, a Bharatanatyam and Kathakali dancer, founded the Darpana Academy of Performing Arts in Ahmedabad in 1949.","e":"Her daughter Mallika Sarabhai now leads Darpana.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0353","q":"The Kathak exponent who established the Kadamb School of Dance and Music in Ahmedabad and is known for her innovative choreography is:","o":["Shovana Narayan","Kumudini Lakhia","Maya Rao","Sitara Devi"],"a":1,"x":"Kumudini Lakhia, a Kathak innovator, founded the Kadamb Centre for Dance and Music in Ahmedabad in 1967.","e":"She received the Padma Vibhushan in 2025.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0362","q":"The two kings of Travancore, _________, structured the Mohiniyattam dance form of Kerala into its present classical form in the 18th–19th centuries.","o":["Anizham Tirunal and Uthrittathi Tirunal","Kartika Tirunal and Swati Tirunal","Moolam Tirunal and Chithira Tirunal","Avittom Tirunal and Vaisakha Tirunal"],"a":1,"x":"Mohiniyattam was given its present classical form by the Travancore kings Kartika Tirunal and Swathi Tirunal in the 18th–19th centuries; Vallathol revived it at Kerala Kalamandalam (1930).","e":"Mohiniyattam is a solo, graceful women's dance of Kerala in the lasya style.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0399","q":"Which classical dance form originated in the temples of Northern India and is characterised by intricate footwork and storytelling through mime?","o":["Bharatanatyam","Kathak","Kathakali","Kuchipudi"],"a":1,"x":"Kathak comes from north India's storytellers (kathakars), with fast footwork (tatkar), spins (chakkar) and mime.","e":"Gharanas: Lucknow, Jaipur, Banaras. Birju Maharaj belonged to the Lucknow gharana.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0403","q":"The famous classical dancer Kalamandalam Ramankutty Nair is associated with which dance form?","o":["Bharatanatyam","Odissi","Kathak","Kathakali"],"a":3,"x":"Kalamandalam Ramankutty Nair (1925–2013) was a great Kathakali actor, known for playing Hanuman and Ravana.","e":"Kathakali, from Kerala, uses elaborate make-up: green (pacha) for noble heroes.","src":["ASO 22 Aug 2025 S1"]},{"id":"q0430","q":"To whom is the ancient Sanskrit text 'Natya Shastra' credited?","o":["Vyasa","Patanjali","Bharata Muni","Panini"],"a":2,"x":"The Natya Shastra, the ancient Sanskrit treatise on drama, dance and music, is credited to Bharata Muni.","e":"It sets out the nine rasas (navarasa) and the concept of bhava.","src":["ASO 22 Aug 2025 S1"]},{"id":"q0465","q":"Kalamandalam Gopi is associated with which Indian classical dance form?","o":["Mohiniyattam","Kathakali","Odissi","Bharatanatyam"],"a":1,"x":"Kalamandalam Gopi is a leading Kathakali artist from Kerala, famous for 'pacha' (hero) roles such as Nala and Arjuna.","e":"He received the Padma Shri in 2009.","src":["ASO 27 Aug 2025 S1"]},{"id":"q0478","q":"What is the term used to refer to the intricate and rhythmic footwork performed by Kathak dancers?","o":["Tatkar","Thattimetti","Mudras","Bhramari"],"a":0,"x":"Tatkar is the rhythmic footwork of Kathak, with ghungroos (bells) sounding the taal.","e":"Chakkar: the fast spins of Kathak.","src":["ASO 27 Aug 2025 S1"]},{"id":"q1565","q":"Which of the following dances is NOT from eastern India?","o":["Bagh Nach","Ghumura","Kud dance","Chhau dance"],"a":2,"x":"Kud is a folk dance of Jammu and Kashmir, performed at night to honour Lok Devtas. Bagh Nach and Ghumura (Odisha) and Chhau (Odisha, Jharkhand, Bengal) are from eastern India.","e":"Chhau has three styles: Seraikela, Purulia and Mayurbhanj.","src":["Patwari 17 Sep 2022 S3"]},{"id":"q1576","q":"Bakho-Bakhain and Panwariya are the dance forms of which state?","o":["Odisha","Bihar","Chhattisgarh","Uttarakhand"],"a":1,"x":"Bakho-Bakhain and Panwariya are folk dances of Bihar.","e":"Other Bihar dances: Jat-Jatin, Jhijhiya, Bidesia (folk theatre).","src":["Patwari 18 Sep 2022 S1"]},{"id":"q1583","q":"The Ministry of Culture, Government of India has included Chhau into the list of classical dances that makes a total of how many classical dance forms in India?","o":["8","7","10","9"],"a":3,"x":"The Ministry of Culture lists 9 classical dances, adding Chhau to the Sangeet Natak Akademi's 8: Bharatanatyam, Kathak, Kathakali, Kuchipudi, Odissi, Manipuri, Mohiniyattam and Sattriya.","e":"Sattriya (Assam) was the last added by the Akademi, in 2000.","src":["Patwari 20 Aug 2022 S1"],"k":"Many books still say 8 (the Sangeet Natak Akademi list). This question's key follows the Ministry of Culture, which gives 9."},{"id":"q1621","q":"Which of the following Bhavas that are expressed in the classical dance are NOT matched properly to the meaning given in front of them?","o":["Shringar: Love","Adbhoot: Wonder","Karuna: Humorous","Bibhats: Disgust"],"a":2,"x":"Karuna means compassion or pathos, not humour (humour is hasya). The other pairs are right: shringara–love, adbhuta–wonder, bibhatsa–disgust.","e":"The nine rasas: shringara, hasya, karuna, raudra, veera, bhayanaka, bibhatsa, adbhuta, shanta.","src":["Patwari 20 Aug 2022 S1"]},{"id":"q0484","q":"Which among the following dance forms of Gujarat was originally performed after the successful hunting of animals?","o":["Siddi Dhamal","Padhar","Dandiya","Tippani"],"a":0,"x":"Siddi Dhamal is performed by the Siddi community of Gujarat, of African origin, and was originally danced after a successful hunt.","e":"Gujarat's best-known folk dances: Garba and Dandiya Raas.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0524","q":"Dhol Cholom, a drum dance, is one of the dances performed during which of the following festivals in Manipur?","o":["Holi","Diwali","Navratri","Ganesh Chaturthi"],"a":0,"x":"Dhol Cholom, the drum dance of Manipur, is performed during Holi (Yaoshang) celebrations.","e":"Pung Cholom is the related mridanga (pung) dance.","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0563","q":"The Ghumura dance form of Odisha is performed 15 days before the arrival of full moon in the month of ___________.","o":["October","September","May","June"],"a":1,"x":"Ghumura, the drum-dance of Kalahandi (western Odisha), is traditionally performed in the weeks before Dussehra, around September.","e":"The ghumura drum is an earthen pot covered with lizard skin.","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0603","q":"Zemmado is an interesting dance form in which women belonging to the Dhangar community of Goa imitate the actions of which of the following animals?","o":["Elephant","Lion","Goat","Cow"],"a":2,"x":"Zemmado is a Goan folk dance of Dhangar women that imitates the movements of goats, the animals they herd.","e":"The Dhangars are a shepherd community of Goa and Maharashtra.","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0643","q":"In which of the following dance forms of Rajasthan, women dancers carry earthen or brass pots which are set on fire?","o":["Chari","Kalbeliya","Ghoomar","Kachchhi"],"a":0,"x":"In the Chari dance of Rajasthan's Kishangarh (Gujjar community), women dance balancing brass pots (charis) on their heads, with lit cotton seeds dipped in oil in them.","e":"Other Rajasthan dances: Ghoomar (Bhil and Rajput), Kalbeliya (snake-charmer community), Kachchhi Ghodi.","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0683","q":"Morulem is a traditional folk dance in Goa performed during which of the following festivals?","o":["Sunburn Festival","Shigmo Festival","Carnival","Lokrang Festival"],"a":1,"x":"Morulem is a folk dance of Goa performed during Shigmo, the spring festival of Goa.","e":"Other Goan dances: Dekhni, Fugdi, Kunbi.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0721","q":"Mrinalini Sarabhai was trained in which one of the following dance forms?","o":["Gotipua","Bihu","Bharatnatyam","Lavani"],"a":2,"x":"Mrinalini Sarabhai trained in Bharatanatyam (and Kathakali) and founded the Darpana Academy in Ahmedabad.","e":"Gotipua is from Odisha; Lavani from Maharashtra; Bihu from Assam.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q1297","q":"For which of the following dance-forms is Shovana Narayana very renowned?","o":["Bharatnatyam","Kathak","Lavani","Odissi"],"a":1,"x":"Shovana Narayan is a renowned Kathak dancer, awarded the Padma Shri in 1992.","e":"Other Kathak names: Birju Maharaj, Sitara Devi, Kumudini Lakhia.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1330","q":"Which among the following dance forms of Madhya Pradesh is also known as \"Harvest Dance\"?","o":["Bhagoria","Tertali","Matki","Jawara"],"a":3,"x":"Jawara is a harvest dance of Madhya Pradesh's Bundelkhand region, performed by men and women carrying baskets of jawara (sprouted grain).","e":"Other MP dances: Matki, Tertali, Bhagoria.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q0978","q":"The Hurka Baul dance form belongs to which state?","o":["Punjab","Uttar Pradesh","West Bengal","Uttarakhand"],"a":3,"x":"Hurka Baul is a folk dance-song of Uttarakhand, performed in the fields during paddy and maize planting to the beat of the hurka drum.","e":"Other Uttarakhand dances: Choliya, Langvir Nritya, Barada Nati.","src":["PRT 18 Feb 2026 S3"]},{"id":"q1044","q":"Which classical dance form, originating from Kerala, is known for its elaborate facial expressions and hand gestures?","o":["Kathakali","Kuchipudi","Manipuri","Mohiniyattam"],"a":0,"x":"Kathakali of Kerala is known for its elaborate make-up, costumes, facial expressions (abhinaya) and hand gestures (mudras).","e":"It is traditionally performed by men, often all night.","src":["PRT 20 Feb 2026 S1"]},{"id":"q1051","q":"Which of the following is a popular folk dance form of Punjab performed during harvest festivals?","o":["Bhangra","Ghoomar","Lavani","Garba"],"a":0,"x":"Bhangra is Punjab's energetic harvest folk dance, performed around Baisakhi to the dhol.","e":"Giddha is the women's folk dance of Punjab.","src":["PRT 20 Feb 2026 S1"]},{"id":"q1248","q":"In which languages are the songs of Kuchipudi dance mainly composed?","o":["Sanskrit and Telugu","Tamil and Kannada","Malayalam and Marathi","Hindi"],"a":0,"x":"Kuchipudi songs are mainly in Telugu and Sanskrit; the dance comes from Kuchipudi village in Andhra Pradesh.","e":"Tarangam is the Kuchipudi item danced on the rim of a brass plate.","src":["PRT 3 Apr 2026 S2"]},{"id":"q1259","q":"The tribal dance form “Karma” is traditionally performed by which community?","o":["Oraon","Apatani","Garo","Bhil"],"a":0,"x":"The Karma dance of the Karma festival is traditionally performed by the Oraon people (and other tribes such as the Munda) of Jharkhand, Chhattisgarh and Odisha.","e":"It celebrates the Karam tree, a symbol of fortune.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1380","q":"The Garadi dance is a popular folk dance of which part of India?","o":["South India","West India","North India","North-east India"],"a":0,"x":"Garadi is a folk dance of Puducherry in south India, performed during festivals and linked with the legend of Rama's victory.","e":"Dancers wear bells and costumes resembling monkeys (vanaras).","src":["TGT 24 Jun 2023 S2"]},{"id":"q1395","q":"‘Buiya’ is a popular folk-dance form of which of the following states?","o":["Mizoram","Nagaland","Arunachal Pradesh","Manipur"],"a":2,"x":"Buiya is a folk dance of the Digaru Mishmi people of Arunachal Pradesh.","e":"Other Arunachal dances: Bardo Chham, Ponung, Aji Lamu.","src":["TGT 24 Jun 2023 S3"]},{"id":"q1421","q":"Terms such as ‘Pada Bheda’, ‘Chalis’ and ‘Bhramaris’ are associated with the techniques of which of the following dance forms?","o":["Odissi","Kathakali","Ghoomar","Manipuri"],"a":0,"x":"Pada bheda (foot positions), chalis (gaits) and bhramaris (turns) are Odissi technique terms.","e":"Odissi's basic stances: tribhanga and chowk.","src":["TGT 25 Jun 2023 S1"]},{"id":"q1430","q":"Which dance form was known as 'Dasi Attam' in earlier times?","o":["Mohiniattam","Bharatnatyam","Kathak","Bihu"],"a":1,"x":"Bharatanatyam was once called 'Dasi Attam' or 'Sadir', danced by devadasis in Tamil Nadu temples; E. Krishna Iyer and Rukmini Devi Arundale revived it.","e":"Rukmini Devi founded Kalakshetra in Chennai (1936).","src":["TGT 25 Jun 2023 S2"]},{"id":"q1514","q":"Which dancer is credited with integrating various traditions and techniques into their dance dramas?","o":["Uday Shankar","Sonal Mansingh","Birju Maharaj","Yamini Krishnamurthy"],"a":0,"x":"Uday Shankar, the pioneer of modern Indian dance, mixed classical, folk and Western stagecraft in his dance dramas; he set up the Almora cultural centre (1938).","e":"He was the elder brother of sitar maestro Ravi Shankar.","src":["TGT 24 Aug 2025 S1"]},{"id":"q1521","q":"Who among the following Bharatnatyam and Kuchipudi dancers has been conferred with the Padma Shri, the Padma Bhushan and the Padma Vibhushan?","o":["Mrinalini Sarabhai","Yamini Krishnamurthy","Kalamandalam Kalyanikutty Amma","Shovana Narayan"],"a":1,"x":"Yamini Krishnamurthy, the Bharatanatyam and Kuchipudi exponent, received the Padma Shri (1968), Padma Bhushan (2001) and Padma Vibhushan (2016).","e":"She ran a dance institute in Delhi.","src":["TGT 24 Aug 2025 S1"]},{"id":"q1542","q":"The dance form named after the mythical character Mohini belongs to which state?","o":["Tamil Nadu","Karnataka","Andhra Pradesh","Kerala"],"a":3,"x":"Mohiniyattam, named after Mohini (Vishnu's enchantress form), is the classical dance of Kerala.","e":"'Mohini' + 'attam' (dance) = the dance of the enchantress.","src":["TGT 24 Aug 2025 S3"]}]},{"id":"music","n":"Music and Instruments","qs":[{"id":"q0009","q":"The two distinct forms of Indian Classical Music, Hindustani and Carnatic, came into existence:","o":["after the advent of the French","after the advent of the British","after the advent of the Portuguese","after the advent of Muslims"],"a":3,"x":"Indian music split into the Hindustani (north) and Carnatic (south) traditions after the 13th century, when Persian and Central Asian influences reshaped northern music under the Delhi Sultanate.","e":"Amir Khusrau (13th–14th century) is credited with shaping early Hindustani forms such as qawwali.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0032","q":"Which of the following is NOT a general part of Indian classical music?","o":["Beats (Taal)","Rhythm (Laya)","Notes (Sur)","Devotion (Bhakti)"],"a":3,"x":"Classical music rests on swara or sur (notes), raga (melody), taal (rhythmic cycle) and laya (tempo). Devotion is a mood or theme, not a structural part.","e":"Teentaal, the most common Hindustani taal, has 16 beats.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0143","q":"Which of the following is a Hindustani classical vocal style known for its slow and meditative approach?","o":["Thumri","Tappa","Khayal","Dhrupad"],"a":3,"x":"Dhrupad is the oldest surviving Hindustani vocal style — slow, grave and meditative, and usually devotional.","e":"Masters: Tansen and the Dagar family. Khayal, thumri and tappa are later and lighter.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0192","q":"In Hindustani classical music, how can a 'raga' best be described?","o":["A form of Western notation","A rhythmic cycle","A type of musical instrument","A melodic framework for improvisation"],"a":3,"x":"A raga is a melodic framework — a set of notes with rules of ascent, descent and characteristic phrases — within which the performer improvises.","e":"A taal is the rhythmic cycle, not the raga.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0242","q":"The term ‘taal’ in Hindustani classical music refers to ___________.","o":["the rhythm or rhythmic cycle","the mood or emotion of the piece","the melody being performed","the tempo of the music"],"a":0,"x":"Taal is the rhythmic cycle of Indian classical music, a fixed number of beats (matras) grouped in sections.","e":"Teentaal: 16 beats; Jhaptaal: 10; Rupak: 7; Dadra: 6.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0244","q":"Ustad Hassu Khan and Ustad Haddu Khan are accredited to be the founders of the ______________________.","o":["Gwalior Gharana","Kirana Gharana","Banaras Gharana","Agra Gharana"],"a":0,"x":"Ustad Hassu Khan and Haddu Khan are regarded as founders of the Gwalior Gharana, the oldest khayal gharana.","e":"Kirana Gharana: Abdul Karim Khan. Agra: Faiyaz Khan. Jaipur-Atrauli: Alladiya Khan.","src":["ASO 20 Aug 2025 S2"]},{"id":"q1564","q":"Which of the following is a folk music of Bengal?","o":["Bhavageet","Baryi","Bihugeet","Baul"],"a":3,"x":"Baul is the mystic folk music of Bengal (West Bengal and Bangladesh), sung by wandering minstrels with the ektara. UNESCO lists it as intangible heritage.","e":"Bhavageete is from Karnataka; Bihugeet from Assam.","src":["Patwari 17 Sep 2022 S3"]},{"id":"q1587","q":"Famous Sawai Gandharv Bhimsen Mahotsav music festival is organized in which of the following cities?","o":["Indore","Pune","Agra","Jaipur"],"a":1,"x":"The Sawai Gandharva Bhimsen Mahotsav, a major Hindustani classical music festival, is held in Pune every December; Pandit Bhimsen Joshi started it in 1953.","e":"Bhimsen Joshi (Kirana gharana) received the Bharat Ratna in 2009.","src":["Patwari 20 Aug 2022 S2"]},{"id":"q0481","q":"Which among the following folk music of Madhya Pradesh is a heroic ballad song with intricate words?","o":["Alha","Pandavani","Pai","Dadra"],"a":0,"x":"Alha is a heroic ballad of Madhya Pradesh's Bundelkhand, telling of the warrior brothers Alha and Udal, and is sung in the rainy season.","e":"Pandavani (Chhattisgarh) retells the Mahabharata; Teejan Bai is its famous singer.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0522","q":"The Marfa music is associated with which of the following cities?","o":["Nagpur","Hyderabad","Kolkata","Bangalore"],"a":1,"x":"Marfa music is the rhythmic drum-and-daf music of the Hyderabadi Siddis (of African origin), played at weddings and celebrations in Hyderabad.","e":"It came with Siddi soldiers of the Nizams.","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0564","q":"Borgeet is a Vaishnava devotional song, popular in which of the following states?","o":["Assam","Manipur","Meghalaya","Nagaland"],"a":0,"x":"Borgeet are Vaishnava devotional songs of Assam, composed by Srimanta Sankardeva and Madhavdeva in the 15th–16th centuries.","e":"Sankardeva also founded Sattriya dance and the satras (monasteries).","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0602","q":"The Pai songs are most popular folk songs in which of the following states?","o":["Maharashtra","Madhya Pradesh","Andhra Pradesh","West Bengal"],"a":1,"x":"Pai songs are sung in Madhya Pradesh, especially by Gond tribal people, at festivals.","e":"Other MP folk songs: Alha, Faag, Bhartrahari.","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0644","q":"Which among the following folk music narrates the social and political conditions of Jammu and Kashmir?","o":["Jhoori","Surma","Chakri","Ladishah"],"a":3,"x":"Ladishah is a satirical folk ballad of Jammu and Kashmir: a wandering singer comments on social and political conditions, keeping rhythm with an iron rod (dhukar).","e":"Chakri is Kashmir's popular folk music, sung with the rabab and harmonium.","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0684","q":"Ainchaliyan is a type of religious songs often sung to a newly wed bride or to an unmarried girl, who is expected to get married in near future. It is associated with which of the following states?","o":["Himachal Pradesh","Uttar Pradesh","Haryana","Punjab"],"a":0,"x":"Ainchaliyan are religious folk songs of Himachal Pradesh, sung for a newly married bride or a girl soon to be married.","e":"Other Himachal folk songs: Laman, Jhoori.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0722","q":"Amongst the following, Annapurna Devi was a notable performer of which musical instrument?","o":["Sarangi","Ghatam","Pakhawaj","Surbahar"],"a":3,"x":"Annapurna Devi, daughter of Ustad Allauddin Khan, was a great surbahar (bass sitar) player and guru of Hariprasad Chaurasia and Nikhil Banerjee.","e":"She was married to Pandit Ravi Shankar.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q1331","q":"Which among the following folk music evolved among the Goan Catholics of Goa?","o":["Maand","Powada","Bhavageete","Mando"],"a":3,"x":"Mando is a folk song-dance form of Goa's Catholics, blending Indian and Portuguese musical traditions.","e":"Dulpod is the faster Goan song that often follows a Mando.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1384","q":"Which of the following pairs of personality and the associated musical instrument is NOT matched correctly?","o":["Zakir Hussain - Tabla","Bismillah Khan -Shehnai","Bhajan Sopori - Veena","Hari Prasad Chaurasia - Flute"],"a":2,"x":"Bhajan Sopori was a santoor player from Kashmir, not a veena player. The other pairs are correct.","e":"Other santoor maestro: Shivkumar Sharma.","src":["TGT 24 Jun 2023 S3"]},{"id":"q1417","q":"Who among the following is NOT amongst the Trinity of Carnatic music?","o":["Tyagaraja","Syama Sastri","Tenali Raman","Muthuswami Dikshitar"],"a":2,"x":"The Trinity of Carnatic music is Tyagaraja, Muthuswami Dikshitar and Syama Sastri, all of the 18th–19th centuries. Tenali Raman was a poet at Krishnadevaraya's court.","e":"Purandara Dasa is called the 'father of Carnatic music'.","src":["TGT 25 Jun 2023 S1"]},{"id":"q1432","q":"Ustad Zakir Hussain, the Indian music maestro, is known for playing which instrument?","o":["Flute","Tabla","Santoor","Harmonica"],"a":1,"x":"Ustad Zakir Hussain was a tabla maestro, son of Ustad Alla Rakha, and a Padma Vibhushan and Grammy winner.","e":"Other tabla greats: Alla Rakha, Kishan Maharaj.","src":["TGT 25 Jun 2023 S2"]},{"id":"q1551","q":"To propagate Indian Dance and Music, the erstwhile government of united Andhra Pradesh started Sri Thyagaraja Government college of Music and Dance in the year 1952 at _________.","o":["Hyderabad","Vizianagaram","Kakinada","Visakhapatnam"],"a":0,"x":"Sri Thyagaraja Government College of Music and Dance was set up in Hyderabad in 1952 to promote Indian music and dance.","e":"It is named after the Carnatic composer Tyagaraja.","src":["TGT 31 Aug 2025 S1"]}]},{"id":"festivals","n":"Fairs and Festivals","qs":[{"id":"q1568","q":"Which of the following is celebrated in Assam to pray for the standing crops?","o":["Kati Bihu","Rongali Bihu","Bohag Bihu","Magh Bihu"],"a":0,"x":"Kati (Kongali) Bihu in October–November is when Assamese farmers light earthen lamps in the paddy fields to pray for the standing crop.","e":"The three Bihus: Rongali/Bohag (April, new year), Kati/Kongali (October), Bhogali/Magh (January, harvest).","src":["Patwari 17 Sep 2022 S3"]},{"id":"q1585","q":"In which state is the festival of Bastar Dussehra celebrated?","o":["Bihar","Maharashtra","Chhattisgarh","Uttar Pradesh"],"a":2,"x":"Bastar Dussehra in Jagdalpur, Chhattisgarh, runs for about 75 days and honours goddess Danteshwari, not Rama.","e":"It is among the longest festivals in the world.","src":["Patwari 20 Aug 2022 S1"]},{"id":"q1617","q":"The Chapcharkut Festival is celebrated in which of the following state?","o":["Sikkim","Mizoram","Tripura","Assam"],"a":1,"x":"Chapchar Kut, Mizoram's spring festival, is held in March after jungle-clearing for jhum (shifting) cultivation.","e":"Other Mizo festivals: Mim Kut and Pawl Kut (harvest).","src":["Patwari 18 Sep 2022 S1"]},{"id":"q0483","q":"The Chhari Festival is celebrated in which of the following states/union territories of India?","o":["Odisha","Haryana","Karnataka","Jammu and Kashmir"],"a":3,"x":"The Chhari festival belongs to Jammu and Kashmir: the holy mace (Chhari Mubarak) of Lord Shiva is carried to the Amarnath cave.","e":"The Amarnath Yatra ends on Shravan Purnima (Raksha Bandhan).","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0523","q":"Karma is a harvest festival which is held on the 11th day of a Purnima of the Hindu month of ___________.","o":["Chaith","Kartik","Phagun","Bhado"],"a":3,"x":"Karma, the tribal harvest festival of Jharkhand, Chhattisgarh and Odisha, is held on the 11th day of the bright fortnight (Purnima) of Bhado (Bhadrapada).","e":"People dance around a branch of the Karam tree.","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0562","q":"The Gochi Festival is associated with which of the following states?","o":["Assam","Haryana","Himachal Pradesh","Madhya Pradesh"],"a":2,"x":"Gochi is a festival of the Lahaul valley in Himachal Pradesh, celebrated in February for the birth of sons in the past year.","e":"Other Himachal fairs: Kullu Dussehra, Minjar (Chamba), Lavi (Rampur).","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0604","q":"Kharchi Puja is a festival which involves worshipping of ____________ gods who forms the dynasty deity of the Tripuri people.","o":["11","12","13","14"],"a":3,"x":"Kharchi Puja in Agartala, Tripura (July), worships 14 gods (Chaturdasha Devata), the family deities of the Tripuri royal line.","e":"It is a week-long festival.","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0642","q":"The Bhadu Festival celebrates the transformation of Princess Bhadreswari into a cult figure. It is celebrated in which of the following states?","o":["Karnataka","West Bengal","Kerala","Maharashtra"],"a":1,"x":"Bhadu is a harvest-season festival of West Bengal's Purulia, Bankura and Birbhum districts in the month of Bhadra, honouring Princess Bhadreswari of Kashipur, who became a folk goddess.","e":"Tusu is another Bengal–Jharkhand folk festival, held in Paush (January).","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0682","q":"Dhanuyatra is a great mass festival of Odisha which is based on the noble deeds of Lord ____________.","o":["Ram","Ganesh","Krishna","Hanuman"],"a":2,"x":"Dhanu Yatra, held in Bargarh, Odisha, re-enacts Lord Krishna's story up to Kansa's death; the whole town becomes the stage.","e":"It is described as the world's largest open-air theatre.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q1300","q":"In which of the following states is the Bihula festival very popular?","o":["Bihar","Madhya Pradesh","Odisha","Gujarat"],"a":0,"x":"Bihula (Bishahari) puja, honouring the snake goddess Manasa and the devoted Behula, is popular in the Bhagalpur region of Bihar.","e":"Manjusha art of Bhagalpur illustrates the Bihula–Bishahari story.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1470","q":"The Nalwari Fair is a cattle fair celebrated in which state?","o":["Tamil Nadu","Himachal Pradesh","Assam","Gujarat"],"a":1,"x":"The Nalwari Fair is a cattle fair held in March at Bilaspur, Himachal Pradesh.","e":"Other Himachal fairs: Minjar (Chamba), Lavi (Rampur), Shivratri (Mandi).","src":["TGT 7 Feb 2024 S2"]}]},{"id":"art","n":"Monuments, Art and Architecture","qs":[{"id":"q0001","q":"In which of the following States of India is the Bolgatty Palace located?","o":["Punjab","Goa","Karnataka","Kerala"],"a":3,"x":"Bolgatty Palace stands on Bolgatty (Mulavukad) Island off Kochi, Kerala. The Dutch built it in 1744; it later became the home of the British Resident.","e":"Kochi's two palace names to keep apart: Bolgatty Palace and Mattancherry (the Dutch Palace).","src":["ASO 18 Aug 2025 S1"]},{"id":"q0069","q":"The Bagh Caves are considered important examples of which architectural tradition?","o":["Islamic architecture","Hindu architecture","Jain architecture","Buddhist architecture"],"a":3,"x":"The Bagh Caves (Dhar district, Madhya Pradesh) are nine rock-cut Buddhist monasteries from the Gupta period, famous for murals similar to Ajanta's.","e":"Buddhist rock-cut sites: Ajanta, Bagh, Karla, Bhaja, Kanheri. Ellora mixes Buddhist, Hindu and Jain caves.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0092","q":"Which of the following is a prominent example of British colonial architecture in India?","o":["Konark Temple","Hawa Mahal","Victoria Memorial","Sun Temple"],"a":2,"x":"The Victoria Memorial in Kolkata (1906–1921), in white Makrana marble, is a leading example of British colonial (Indo-Saracenic) architecture.","e":"Other colonial landmarks: Gateway of India (Mumbai), Chhatrapati Shivaji Terminus, Rashtrapati Bhavan (Lutyens).","src":["ASO 18 Aug 2025 S3"]},{"id":"q0112","q":"The Sanchi Stupa has how many profusely carved ornamental gateways?","o":["Four","Two","Three","Six"],"a":0,"x":"The Great Stupa at Sanchi has four elaborately carved toranas (gateways), one at each cardinal direction, added in the 1st century BCE.","e":"Ashoka commissioned the original brick stupa in the 3rd century BCE.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0125","q":"In which of the following centuries was the Jagannath temple built?","o":["9th century AD","12th century AD","11th century AD","13th century AD"],"a":1,"x":"The present Jagannath Temple at Puri was built in the 12th century by Anantavarman Chodaganga Deva of the Eastern Ganga dynasty.","e":"Puri is one of the four Char Dham; its Rath Yatra takes place in Ashadha (June–July).","src":["ASO 19 Aug 2025 S2"]},{"id":"q0149","q":"The Brihadeeswara Temple in Thanjavur is primarily dedicated to which Hindu deity?","o":["Lord Vishnu","Lord Ganesha","Lord Shiva","Goddess Durga"],"a":2,"x":"The Brihadeeswara Temple at Thanjavur, built by Rajaraja Chola I (completed 1010 CE), is dedicated to Lord Shiva.","e":"It is part of the UNESCO 'Great Living Chola Temples' with Gangaikondacholapuram and Darasuram.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0150","q":"Which of the following temples is known for its grand architecture, including a massive statue of Nandi and the tallest tower in the world?","o":["Meenakshi Temple, Madurai","Somnath Temple, Gujarat","Brihadeeswara Temple, Thanjavur","Virupaksha Temple, Hampi"],"a":2,"x":"The Brihadeeswara Temple at Thanjavur has a huge monolithic Nandi and a vimana about 66 m tall, among the tallest temple towers of its age.","e":"The capstone at the top of the vimana is said to weigh about 25 tonnes.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0159","q":"Which landmark is a major example of colonial architecture in Kolkata?","o":["Basilica of Bom Jesus","National Gallery of Modern Art","Gateway of India","Victoria Memorial"],"a":3,"x":"The Victoria Memorial in Kolkata is the city's best-known colonial monument, designed by William Emerson.","e":"Basilica of Bom Jesus is in Goa; Gateway of India is in Mumbai.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0168","q":"Which of the following is correctly matched with respect to the location of monuments?","o":["Mehrangarh Fort - Amritsar","Hawa Mahal - Jabalpur","Mecca Masjid - Hyderabad","Golconda Fort - Bijapur"],"a":2,"x":"Mecca Masjid is in Hyderabad, begun under Muhammad Quli Qutb Shah in 1617. Mehrangarh is in Jodhpur, Hawa Mahal in Jaipur, and Golconda Fort in Hyderabad.","e":"Gol Gumbaz is the famous monument of Bijapur.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0201","q":"In which of the following states of India, Kunjaban Palace, also known as‘Pushpabanta Palace’, is located?","o":["Bihar","Rajasthan","Meghalaya","Tripura"],"a":3,"x":"Kunjaban Palace, also called Pushpabanta Palace, is in Agartala, Tripura, built by Maharaja Birendra Kishore Manikya in 1917. It is now the official residence of the Governor.","e":"Agartala's other palace, Ujjayanta Palace, now houses the state museum.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0207","q":"The lofty and impressive gates of South Indian styles of temples are known as ______.","o":["vimanas","mandapas","gopurams","shikharas"],"a":2,"x":"Gopurams are the tall, carved gateway towers of South Indian (Dravida) temples.","e":"The tower over the sanctum is the vimana in the south and the shikhara in the north.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0212","q":"The Namdroling Monastery, popularly referred to as‘The Golden Temple ’, is one of the largest Tibetan settlements in India located in the state of _____.","o":["Karnataka","Goa","Bihar","Maharashtra"],"a":0,"x":"Namdroling Monastery, the 'Golden Temple' at Bylakuppe near Kushalnagar in Karnataka, is a major Nyingma monastery in one of the largest Tibetan settlements in India.","e":"Tawang Monastery in Arunachal Pradesh is India's largest monastery.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0225","q":"The Sun Temple at Konark is considered an invaluable link in the history of the diffusion of the cult of Surya. Which region is believed to have been the origin of this cult in the 8th Century?","o":["Kashmir","Tamil Nadu","Rajasthan","Maharashtra"],"a":0,"x":"UNESCO describes Konark as a link in the spread of the Surya cult, which began in Kashmir in the 8th century and reached eastern India.","e":"The Konark Sun Temple (13th century, Narasimhadeva I of the Eastern Gangas) is built as a chariot with 24 wheels.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0235","q":"In which of the following years, the Chapora Fort of Goa was built by the Portuguese?","o":["1617","1607","1727","1787"],"a":0,"x":"The present Chapora Fort in North Goa was built by the Portuguese in 1617 on the site of an earlier Adil Shahi fort.","e":"It became famous as the 'Dil Chahta Hai fort'.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0292","q":"Which monastery belongs to the Nyingma sect of Tibetan Buddhism founded in 1701 CE?","o":["Dubdi Monastery","Kardang Monastery","Likir Monastery","Gandhola Monastery"],"a":0,"x":"Dubdi Monastery at Yuksom, Sikkim, founded in 1701, belongs to the Nyingma sect and is considered Sikkim's oldest monastery.","e":"Yuksom was Sikkim's first capital (1642).","src":["ASO 20 Aug 2025 S3"]},{"id":"q0299","q":"Naggar Castle, a 15th-century historic fort-palace, is located in which of the following states of India?","o":["Bihar","Andhra Pradesh","Tripura","Himachal Pradesh"],"a":3,"x":"Naggar Castle, a 15th-century stone and timber fort-palace in the Kullu valley, is in Himachal Pradesh.","e":"Nearby is the Nicholas Roerich Art Gallery.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0311","q":"In which year was the foundation stone of the All India War Memorial Arch in Delhi, now known as India Gate, laid?","o":["1921","1931","1926","1939"],"a":0,"x":"The foundation stone of the All India War Memorial (India Gate) in Delhi was laid in 1921 by the Duke of Connaught. Edwin Lutyens designed it and it was finished in 1931.","e":"It honours about 70,000 Indian soldiers killed in World War I.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0313","q":"What is the shape of the main temple tower, known as the vimana, in Dravidian temples?","o":["Curved spire","Dome-like structure","Square","Stepped pyramid"],"a":3,"x":"In Dravida temples the vimana over the sanctum rises as a stepped pyramid; in Nagara (north Indian) temples the shikhara is curvilinear.","e":"Example: the vimana of the Brihadeeswara Temple at Thanjavur.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0316","q":"Most of the main temple sites of ancient Kalinga in Odisha are located in which modern district?","o":["Bhubaneswar district","Konark district","Cuttack district","Puri district"],"a":3,"x":"Most major temple sites of ancient Kalinga are in today's Puri district: the Jagannath Temple and the Konark Sun Temple.","e":"The Lingaraj Temple is in Bhubaneswar (Khordha district).","src":["ASO 20 Aug 2025 S3"]},{"id":"q0333","q":"_________ is associated with the architectural design of the Rashtrapati Bhavan during the period of the British Raj.","o":["Sir Edwin Lutyens","Sir Robert Chisholm","Sir Laurie Baker","Sir Henry Irwin"],"a":0,"x":"Sir Edwin Lutyens designed Rashtrapati Bhavan (formerly Viceroy's House, completed 1929) for the new capital of New Delhi; Herbert Baker designed the North and South Blocks.","e":"Lutyens also designed India Gate.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0363","q":"The 'Se Cathedral' church of Goa was built in the _________ architectural style in the 16th Century.","o":["Italianate","Byzantine","Romanesque","Manueline"],"a":3,"x":"Se Cathedral in Old Goa, built by the Portuguese from 1562, is in Portuguese-Manueline style outside with a Corinthian interior; it is dedicated to St Catherine.","e":"Nearby, the Basilica of Bom Jesus holds the relics of St Francis Xavier.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0391","q":"The Hawa Mahal is located in which Indian city?","o":["Delhi","Jaisalmer","Jaipur","Agra"],"a":2,"x":"Hawa Mahal ('Palace of Winds', 1799) in Jaipur was built by Maharaja Sawai Pratap Singh, with 953 small windows (jharokhas) so royal women could watch the street.","e":"Jaipur is the 'Pink City'; its walled city is a UNESCO World Heritage site.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0431","q":"Who is credited with the construction of the Great Stupa at Sanchi?","o":["Kanishka","Chandragupta Maurya","Ashoka","Harsha"],"a":2,"x":"Emperor Ashoka commissioned the Great Stupa at Sanchi (3rd century BCE) as a brick structure; the Shungas later enlarged it in stone and the Satavahanas added gateways.","e":"Sanchi is in Raisen district, Madhya Pradesh; it is a UNESCO site.","src":["ASO 22 Aug 2025 S1"]},{"id":"q0440","q":"In which state of India is the Sun Temple of Konark located?","o":["Bihar","Odisha","Maharashtra","Karnataka"],"a":1,"x":"The Konark Sun Temple (13th century, Narasimhadeva I of the Eastern Ganga dynasty) is in Puri district, Odisha, and is called the 'Black Pagoda'.","e":"It is shown on the back of the ₹10 note.","src":["ASO 22 Aug 2025 S1"]},{"id":"q0471","q":"Which Buddhist architectural structure is entirely made of brick and still stands, even in the 21st century?","o":["Great Stupa of Sanchi","Mahabodhi Temple","Amaravati Stupa","Dhamek Stupa"],"a":1,"x":"The Mahabodhi Temple at Bodh Gaya is among the earliest Buddhist temples built wholly in brick that still stand; the present structure dates from the 5th–6th century.","e":"It marks where the Buddha attained enlightenment; UNESCO listed it in 2002.","src":["ASO 27 Aug 2025 S1"]},{"id":"q1578","q":"Which of the following is a stone-like disc seen at the top of the Hindu temple, mostly in north Indian temples?","o":["Garbhagriha","Amalaka","Jagati","Antarala"],"a":1,"x":"The amalaka is the ribbed stone disc on top of the shikhara of Nagara (north Indian) temples, with a kalasha above it.","e":"Garbhagriha: sanctum. Antarala: vestibule. Jagati: raised platform.","src":["Patwari 18 Sep 2022 S1"]},{"id":"q1590","q":"In Buddhist architecture what is the meaning of Chaitya Hall?","o":["Recreation Hall","Place of Worship","Hall of Spiritual Leaders","Place for Marriage Ceremony"],"a":1,"x":"A chaitya is a Buddhist prayer hall (place of worship) with a stupa at its far end; a vihara is a monastery where monks live.","e":"Karla and Bhaja (Maharashtra) have famous rock-cut chaityas.","src":["Patwari 20 Aug 2022 S2"]},{"id":"q1600","q":"The 'Bani Thani' painting is associated with which school?","o":["Kishangarh","Mewar","Bundi","Bikaner"],"a":0,"x":"'Bani Thani', called 'India's Mona Lisa', belongs to the Kishangarh school of Rajasthani painting and was painted by Nihal Chand in the 18th century.","e":"A 1973 Indian postage stamp showed Bani Thani.","src":["Patwari 17 Sep 2022 S2"]},{"id":"q0482","q":"Which among the following is also known as \"Harmandir Sahib\"?","o":["Bangla Sahib, Delhi","Golden Temple, Punjab","San Sahib, Punjab","Jagannath Temple, Odisha"],"a":1,"x":"Harmandir Sahib is the Golden Temple at Amritsar, the holiest Sikh gurdwara, built under Guru Arjan Dev (foundation 1588).","e":"Maharaja Ranjit Singh covered it in gold in the 19th century.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0521","q":"The Shalimar Garden of Jammu and Kashmir was built by which of the following Mughal emperor?","o":["Aurangzeb","Jahangir","Shah Jahan","Babur"],"a":1,"x":"The Shalimar Bagh in Srinagar was built by Jahangir in 1619 for Nur Jahan.","e":"Nishat Bagh was built by Asaf Khan, Nur Jahan's brother.","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0601","q":"In which of the following states is the Kumbhalgarh Fort located?","o":["Maharashtra","Tamil Nadu","Rajasthan","Madhya Pradesh"],"a":2,"x":"Kumbhalgarh Fort (15th century, Rana Kumbha) in Rajsamand district, Rajasthan, has one of the world's longest walls (about 36 km); it is a UNESCO Hill Fort of Rajasthan.","e":"Maharana Pratap was born here.","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0641","q":"Who among the following built the Red Fort in Delhi?","o":["Shah Jahan","Akbar","Babur","Humayun"],"a":0,"x":"Shah Jahan built the Red Fort (Lal Qila) in Delhi between 1639 and 1648 when he moved the capital to Shahjahanabad.","e":"The Prime Minister hoists the flag here on Independence Day; it is a UNESCO site.","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0681","q":"Rani ki Vav or 'Queen's Stepwell' is a unique stepwell located in which of the following states?","o":["Gujarat","Madhya Pradesh","Maharashtra","Tamil Nadu"],"a":0,"x":"Rani ki Vav at Patan, Gujarat, was built in the 11th century by Queen Udayamati in memory of Bhimdev I of the Chaulukya (Solanki) dynasty; UNESCO listed it in 2014.","e":"It appears on the back of the ₹100 note.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0724","q":"Jhulta Minar is located in which one of the following states of India?","o":["Uttar Pradesh","Gujarat","Andhra Pradesh","Rajasthan"],"a":1,"x":"The Jhulta Minar (shaking minarets) of the Sidi Bashir Mosque is in Ahmedabad, Gujarat: shake one minaret and the other shakes too.","e":"Ahmedabad was India's first UNESCO World Heritage City (2017).","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q1304","q":"In which of the following states is the Chandragad fort situated?","o":["Karnataka","Andhra Pradesh","Maharashtra","Gujarat"],"a":2,"x":"Chandragad Fort is in the Sahyadris (Western Ghats) of Maharashtra, in Satara district, associated with the Marathas.","e":"Maharashtra has more than 350 forts; Raigad was Shivaji's capital.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q0906","q":"The Kailasa temple at Ellora, viewed as a grand specimen of Rashtrakuta artistry, was built under the patronage of which king?","o":["Indra Varma","Vikramaditya","Krishna II","Krishna I"],"a":3,"x":"The Kailasa (Kailashnath) temple, Cave 16 at Ellora, was cut from a single rock under the Rashtrakuta king Krishna I in the 8th century.","e":"It is the world's largest monolithic rock-cut structure.","src":["PRT 17 Feb 2026 S3"]},{"id":"q0986","q":"Which monument, built by Shah Jahan in memory of his wife Mumtaz Mahal, is a UNESCO World Heritage Site?","o":["Red Fort","Taj Mahal","Qutub Minar","Humayun's Tomb"],"a":1,"x":"Shah Jahan built the Taj Mahal at Agra (1632–53) in memory of Mumtaz Mahal; UNESCO listed it in 1983.","e":"Chief architect: Ustad Ahmad Lahori.","src":["PRT 19 Feb 2026 S1"]},{"id":"q1107","q":"The Warli painting tradition originated in which Indian state?","o":["Odisha","Rajasthan","West Bengal","Maharashtra"],"a":3,"x":"Warli painting comes from the Warli tribe of Maharashtra's Thane–Palghar region, drawn with white rice paste as simple circles, triangles and lines on mud walls.","e":"Madhubani is from Bihar; Pattachitra from Odisha.","src":["PRT 23 Feb 2026 S3"]},{"id":"q1192","q":"Jaisalmer Fort, built by Rawal Jaisal on Trikuta Hill, has how many layers of walls?","o":["four","three","two","five"],"a":1,"x":"Jaisalmer Fort (Sonar Qila, 1156 CE, Rawal Jaisal) on Trikuta Hill has three layers of walls and is a 'living fort' with residents inside.","e":"It is one of UNESCO's Hill Forts of Rajasthan.","src":["PRT 31 Mar 2026 S1"]},{"id":"q1271","q":"During which century was the Quwwat al-Islam mosque and minaret built in Delhi?","o":["Tenth century","Twelfth century","Eleventh century","Fifteenth century"],"a":1,"x":"The Quwwat-ul-Islam mosque and the Qutub Minar in Delhi were begun by Qutbuddin Aibak in the late 12th century (from 1193).","e":"Iltutmish completed the Qutub Minar; Alauddin Khalji added the Alai Darwaza.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1364","q":"Sultan Garhi, built in 1231 for Prince Nasiruddin and regarded as India's first Islamic tomb, is located in which city?","o":["Panipat","Lucknow","Delhi","Agra"],"a":2,"x":"Sultan Garhi (1231), built by Iltutmish for his eldest son Prince Nasiruddin Mahmud, is regarded as India's first Islamic tomb; it is in Delhi.","e":"Iltutmish's own tomb is in the Qutub complex.","src":["TGT 24 Jun 2023 S2"]},{"id":"q1387","q":"Which of the following types of structures is NOT associated with Buddhist architecture in India?","o":["Chaityas","Monkas","Viharas","Stupas"],"a":1,"x":"Buddhist architecture in India includes stupas (relic mounds), chaityas (prayer halls) and viharas (monasteries). 'Monkas' is not a Buddhist structure.","e":"Karla has a famous rock-cut chaitya hall.","src":["TGT 24 Jun 2023 S3"]},{"id":"q1420","q":"The temples at Khajuraho, a UNESCO World Heritage Site, were built during the reign of which of the following dynasties?","o":["Maurya","Chandela","Pallava","Kakatiya"],"a":1,"x":"The Khajuraho temples (950–1050 CE) in Madhya Pradesh were built by the Chandela dynasty; UNESCO listed them in 1986.","e":"The Kandariya Mahadeva is the largest Khajuraho temple.","src":["TGT 25 Jun 2023 S1"]},{"id":"q1422","q":"Which of the following Indian monuments is NOT a UNESCO World Heritage Site?","o":["Red Fort","Char Minar","Taj Mahal","Humayun’s Tomb"],"a":1,"x":"The Charminar in Hyderabad is not a UNESCO World Heritage Site. The Red Fort, Taj Mahal and Humayun's Tomb are.","e":"The Charminar was built by Muhammad Quli Qutb Shah in 1591.","src":["TGT 25 Jun 2023 S1"]},{"id":"q1427","q":"The Ajanta caves of Maharashtra are cave monuments connected with which religion?","o":["Zoroastrianism","Buddhism","Hinduism","Jainism"],"a":1,"x":"The Ajanta Caves (2nd century BCE – 6th century CE) in Maharashtra are Buddhist rock-cut monasteries and prayer halls, famous for their murals.","e":"Ellora has Buddhist, Hindu and Jain caves.","src":["TGT 25 Jun 2023 S2"]},{"id":"q1439","q":"Which of the following monuments is NOT located in Delhi?","o":["Qutub Minar","Alai Minar","Balban's Tomb","Bibi ka Maqbara"],"a":3,"x":"Bibi ka Maqbara, the 'Taj of the Deccan', is at Aurangabad (Chhatrapati Sambhajinagar), Maharashtra, built by Azam Shah for his mother. The Qutub Minar, Alai Minar and Balban's Tomb are in Delhi.","e":"Balban's Tomb in Mehrauli has the first true arch in India.","src":["TGT 25 Jun 2023 S2"]},{"id":"q1463","q":"The dance hall in the Sun Temple at Konark is referred to as _______.","o":["Jamagohana","Nat Mandir","Shikhara","Vimana"],"a":1,"x":"The dance hall (Nata Mandira) of the Konark Sun Temple stands in front of the main temple on a high platform.","e":"The jagamohana (assembly hall) is the part still standing.","src":["TGT 25 Jun 2023 S3"]},{"id":"q0815","q":"The ancient Buddhist stupa, a UNESCO World Heritage Site, located in Madhya Pradesh, is:","o":["Sanchi Stupa","Ajanta Caves","Elephanta Caves","Mahabodhi Temple"],"a":0,"x":"The Great Stupa at Sanchi in Raisen district, Madhya Pradesh, is a UNESCO World Heritage Site (1989).","e":"Ajanta and Elephanta are in Maharashtra; Mahabodhi Temple in Bihar.","src":["PGT 22 Sep 2025"]},{"id":"q0826","q":"Which of the following cities is home to the famous Sun Temple, a UNESCO World Heritage Site?","o":["Hampi","Jaipur","Agra","Konark"],"a":3,"x":"The Sun Temple at Konark, Odisha (13th century, Narasimhadeva I), is a UNESCO World Heritage Site.","e":"It is built as Surya's chariot, with 24 wheels and 7 horses.","src":["PGT 26 Sep 2025"]}]},{"id":"books","n":"Books and Authors","qs":[{"id":"q0265","q":"Which of the following is the first novel in English written by an Indian author?","o":["Anandamath","Mritunjay","The Guide","Rajmohan’s Wife"],"a":3,"x":"Rajmohan's Wife (1864) by Bankim Chandra Chattopadhyay is the first novel in English by an Indian author.","e":"Bankim also wrote Anandamath (1882), which contains 'Vande Mataram'.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0273","q":"'The Autobiography of an Unknown Indian', a significant work in the history of Indian literature, was written by which prominent figure?","o":["Nirad C Chaudhuri","Khushwant Singh","RK Narayan","VS Naipaul"],"a":0,"x":"'The Autobiography of an Unknown Indian' (1951) was written by Nirad C. Chaudhuri.","e":"Also by him: 'Thy Hand, Great Anarch!'","src":["ASO 20 Aug 2025 S2"]},{"id":"q0277","q":"Which of the following books was written by Ram Manohar Lohia, critiquing the role of various leaders in the partition of India?","o":["An Autobiography of an Unknown Indian","Guilty Men of India’s Partition","India Wins Freedom","The Story of My Experiments with Truth"],"a":1,"x":"Ram Manohar Lohia wrote 'Guilty Men of India's Partition' (1960), blaming leaders across parties for Partition.","e":"'India Wins Freedom': Maulana Azad. 'The Story of My Experiments with Truth': Gandhi.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0306","q":"Which literary magazine started by Bankim Chandra Chattopadhyay in 1872 played an important role in promoting Bengali nationalism?","o":["Bharati","Desh","Anandabazar Patrika","Bangadarshan"],"a":3,"x":"Bankim Chandra Chattopadhyay started the Bengali monthly 'Bangadarshan' in 1872; it promoted Bengali literature and nationalism.","e":"Anandamath was first serialised in Bangadarshan.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0546","q":"Which among the following books is not written by Chetan Bhagat?","o":["Revolution 2020","One Indian Girl","What Young India Wants","Sons and Lovers"],"a":3,"x":"'Sons and Lovers' (1913) is by D. H. Lawrence. Chetan Bhagat wrote 'Revolution 2020', 'One Indian Girl' and 'What Young India Wants'.","e":"Chetan Bhagat's first novel: 'Five Point Someone' (2004).","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0585","q":"Who is the author of 'India Divided'?","o":["Jawaharlal Nehru","Rajendra Prasad","Shashi Tharoor","A. P. J. Abdul Kalam"],"a":1,"x":"'India Divided' (1946) was written by Dr Rajendra Prasad, arguing against the two-nation theory.","e":"His autobiography: 'Atmakatha'.","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0625","q":"'Mind Master' is an autobiography of which of the following persons?","o":["Viswanathan Anand","Sachin Tendulkar","Bhagat Singh","Sania Mirza"],"a":0,"x":"'Mind Master: Winning Lessons from a Champion's Life' (2019) is by chess champion Viswanathan Anand, with Susan Ninan.","e":"Anand was India's first Grandmaster (1988).","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0665","q":"'Obama: The Call of History' is written by ____________.","o":["Barack Obama","Peter Baker","Donald Trump","Michelle Obama"],"a":1,"x":"'Obama: The Call of History' (2017) was written by journalist Peter Baker of The New York Times.","e":"Obama's own memoir: 'A Promised Land' (2020).","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0705","q":"Which among the following books is written by Salman Rushdie?","o":["The King of Dark Chamber","The End of Imagination","Between the Assassinations","The Enchantress of Florence"],"a":3,"x":"'The Enchantress of Florence' (2008) is by Salman Rushdie. 'The King of the Dark Chamber' is by Tagore, 'The End of Imagination' by Arundhati Roy, and 'Between the Assassinations' by Aravind Adiga.","e":"Rushdie's 'Midnight's Children' won the Booker Prize in 1981.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0746","q":"Which one of the following is not a literary work by Munshi Premchand?","o":["Shatranj ke Khiladi","Nirmala","Anamdas ka Potha","Gaban"],"a":2,"x":"'Anamdas ka Potha' is by Hazari Prasad Dwivedi. Premchand wrote 'Shatranj ke Khiladi', 'Nirmala' and 'Gaban'.","e":"Premchand's last complete novel: 'Godaan' (1936).","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q1316","q":"Who is the author of the book \"The God of Small Things\"?","o":["Jhumpa Lahiri","Arvind Adiga","Karan Thapar","Arundhati Roy"],"a":3,"x":"'The God of Small Things' (1997) is by Arundhati Roy, who won the Booker Prize for it.","e":"Aravind Adiga won the Booker in 2008 for 'The White Tiger'.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1321","q":"In which of the following languages were the Mangalkavyas written?","o":["Braj","Pali","Bengali","Hindi"],"a":2,"x":"Mangalkavyas are medieval Bengali narrative poems praising deities such as Manasa, Chandi and Dharma.","e":"Example: Mukundaram's 'Chandimangal'.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1352","q":"Which among the following books is not written by Rudyard Kipling?","o":["Midnight's Children","Under the Deodars","In Black and White","The Jungle Book"],"a":0,"x":"'Midnight's Children' (1981) is by Salman Rushdie. Rudyard Kipling wrote 'Under the Deodars', 'In Black and White' and 'The Jungle Book'.","e":"Kipling won the Nobel Prize in Literature in 1907.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1362","q":"Who among the following is the author of 'To Kill a Mockingbird'?","o":["Agatha Christie","Ernest Hemingway","Harper Lee","Arthur Conan Doyle"],"a":2,"x":"'To Kill a Mockingbird' (1960) is by the American author Harper Lee; it won the Pulitzer Prize for Fiction in 1961.","e":"Ernest Hemingway: 'The Old Man and the Sea'. Arthur Conan Doyle: Sherlock Holmes. Agatha Christie: Hercule Poirot.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1472","q":"Who composed the famous Tamil epic Silappadikaram?","o":["Kovalan","Thiruvalluvar","Sattanar","Ilango"],"a":3,"x":"Silappadikaram, one of the Five Great Epics of Tamil literature, was composed by Ilango Adigal; it tells the story of Kannagi and Kovalan.","e":"Its sequel, Manimekalai, is by Sattanar; Thiruvalluvar wrote the Tirukkural.","src":["TGT 7 Feb 2024 S2"]},{"id":"q1539","q":"The famous book 'Pataliputra ki Samragyi' is associated with ________.","o":["Mamta Kalia","Sharad Pagare","Mannu Bhandari","Narendra Kohli"],"a":1,"x":"The Hindi novel 'Pataliputra ki Samragyi' is by Sharad Pagare.","e":"His novel 'Pehla Satyagrahi' is about Kalinga's Kharavela.","src":["TGT 24 Aug 2025 S3"]},{"id":"q1549","q":"Who is the author of the book 'The Argumentative Indian', which explores India's cultural history and diversity?","o":["Salman Rushdie","Arundhati Roy","Amartya Sen","Jhumpa Lahiri"],"a":2,"x":"'The Argumentative Indian' (2005) is by Amartya Sen, who celebrates India's tradition of public debate.","e":"Also by Sen: 'Development as Freedom', 'The Idea of Justice'.","src":["TGT 31 Aug 2025 S1"]}]},{"id":"sports","n":"Sports","qs":[{"id":"q0517","q":"Who among the following holds the record of most wins at the Women's World Team Badminton Championships for the Uber Cup as of 31st March 2020?","o":["United States","Indonesia","Japan","China"],"a":3,"x":"China has won the Uber Cup (women's world team badminton) more often than any other country.","e":"The Thomas Cup is the men's event; India won it for the first time in 2022.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0518","q":"The first three Cricket World Cups were also called ___________ World Cups.","o":["Ecstatic","Prudential","Primary","Historical"],"a":1,"x":"The first three Cricket World Cups (1975, 1979, 1983), all in England, were sponsored by the Prudential insurance company and called the Prudential Cups.","e":"India won the 1983 Prudential Cup under Kapil Dev.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0558","q":"Which among the following teams won the first edition of the ICC Women's T20 World Cup in 2009?","o":["England","Australia","India","New Zealand"],"a":0,"x":"England won the first ICC Women's T20 World Cup in 2009, beating New Zealand in the final at Lord's.","e":"Pakistan won the men's T20 World Cup the same year.","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0598","q":"Which among the following won the first FIFA World Cup held in 1930?","o":["Yugoslavia","Argentina","Uruguay","United States"],"a":2,"x":"Uruguay hosted and won the first FIFA World Cup in 1930, beating Argentina 4–2 in the final.","e":"Most titles: Brazil (5).","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0637","q":"Who among the following hosted the first one-day Cricket World Cup tournament held in 1975?","o":["England","Australia","India","New Zealand"],"a":0,"x":"England hosted the first Cricket World Cup in 1975 (and the next two); West Indies won the first two.","e":"India won in 1983 and 2011.","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0680","q":"With which of the following sports Corbillon Cup is associated?","o":["Badminton","Cricket","Golf","Table Tennis"],"a":3,"x":"The Corbillon Cup is the women's team trophy of the World Table Tennis Championships.","e":"The men's equivalent is the Swaythling Cup.","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0718","q":"Who among the following Indian women has scored the highest aggregate runs in the Women's ODI cricket format as of April 2020?","o":["Harmanpreet Kaur","Smriti Mandhana","Mithali Raj","Deepti Sharma"],"a":2,"x":"Mithali Raj is the highest run-scorer in women's ODI cricket (7,805 runs), a record she held on retiring in 2022.","e":"She was the first woman to cross 7,000 ODI runs.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0720","q":"The Beighton Cup is associated with which of the following sports?","o":["Cricket","Golf","Table Tennis","Hockey"],"a":3,"x":"The Beighton Cup (1895, Kolkata) is one of the world's oldest field hockey tournaments.","e":"Other hockey trophies: Aga Khan Cup, Rangaswamy Cup, Dhyan Chand Trophy.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0756","q":"As of April 2020, who is the highest wicket-taker in one day international in women's cricket?","o":["Ellyse Perry","Catherine Fitzpatrick","Jhulan Goswami","Marizanne Kapp"],"a":2,"x":"Jhulan Goswami is the highest wicket-taker in women's ODIs (255 wickets); she retired in 2022.","e":"She was ICC Women's Cricketer of the Year in 2007.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q0758","q":"Which one of the following was the venue for the first edition of the Commonwealth Games in 1930?","o":["Hamilton, Canada","Kuala Lumpur, Malaysia","London, England","Sydney, Australia"],"a":0,"x":"The first Commonwealth Games (then British Empire Games) were held at Hamilton, Canada, in 1930.","e":"India hosted the 2010 Commonwealth Games in Delhi.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q0759","q":"In which of the following games a player can also be called a raider?","o":["Hockey","Wrestling","Volleyball","Kabaddi"],"a":3,"x":"In kabaddi a raider enters the opponents' half chanting 'kabaddi', tries to touch defenders, and returns without being caught.","e":"Kabaddi team: 7 players on court.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q0760","q":"Amongst the following, who was the first person to score a century for India in Test cricket?","o":["Lala Amarnath","Lalchand Rajput","Dilip Vengsarkar","Sunil Gavaskar"],"a":0,"x":"Lala Amarnath scored India's first Test century, 118 on debut against England at Bombay in 1933.","e":"Sunil Gavaskar was the first player to reach 10,000 Test runs.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q1308","q":"Which of the following teams did Pele play for?","o":["Argentina","Brazil","Spain","Portugal"],"a":1,"x":"Pelé played for Brazil and won three FIFA World Cups (1958, 1962, 1970), a record for a player.","e":"At club level he played for Santos (Brazil) and New York Cosmos.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1315","q":"With which of the following games was Prakash Amritraj associated?","o":["Badminton","Tennis","Football","Golf"],"a":1,"x":"Prakash Amritraj is a tennis player, son of Vijay Amritraj.","e":"Vijay and Anand Amritraj helped India reach the Davis Cup finals in 1974 and 1987.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1353","q":"Who among the following is the first cricket player to be awarded the Arjuna Award?","o":["Chandu Borde","Vijay Manjrekar","Mansoor Ali Khan Pataudi","Salim Durani"],"a":3,"x":"Salim Durani became the first cricketer to receive the Arjuna Award, in 1961.","e":"The Arjuna Awards began in 1961.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1355","q":"Which among the following cricket stadiums is not located in South Africa?","o":["Centurion Park","Kingsmead Stadium","Willowmoore Park","Sophia Gardens"],"a":3,"x":"Sophia Gardens is in Cardiff, Wales. Centurion Park, Kingsmead (Durban) and Willowmoore Park (Benoni) are in South Africa.","e":"Lord's in London is called the 'Home of Cricket'.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1357","q":"Ronjan Sodhi won the Rajiv Gandhi Khel Ratna in 2012 for his contribution in the field of _____________.","o":["wrestling","hockey","shooting","tennis"],"a":2,"x":"Ronjan Sodhi, a double-trap shooter, received the Rajiv Gandhi Khel Ratna (now Major Dhyan Chand Khel Ratna) in 2012.","e":"He won gold at the 2010 Asian Games.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1403","q":"Who among the following was the first woman president of the Indian Olympic Association?","o":["Sania Mirza","MC Mary Kom","PT Usha","Geeta Phogat"],"a":2,"x":"P. T. Usha was elected the first woman president of the Indian Olympic Association in December 2022.","e":"She is called the 'Payyoli Express'.","src":["TGT 24 Jun 2023 S3"]},{"id":"q0795","q":"Which of the following records is NOT related to Sachin Tendulkar?","o":["Most 100s in test matches","Most 100s in one-day international cricket","Most runs in one-day international cricket","Highest runs in a T20 match"],"a":3,"x":"Sachin Tendulkar holds the records for most Test centuries (51), most ODI centuries (49) and most ODI runs (18,426). He has no record for highest runs in a T20 match; he played only one T20 international.","e":"Virat Kohli has since passed his ODI centuries record.","src":["PGT 11 Jul 2025 S1"]}]},{"id":"misc","n":"Awards, Firsts, Days and Organisations","qs":[{"id":"q0079","q":"The Indian Classical languages Malayalam and Kannada are majorly spoken in the Indian states of __________ and Karnataka, respectively.","o":["Goa","Andhra Pradesh","Telangana","Kerala"],"a":3,"x":"Malayalam is the main language of Kerala and Kannada of Karnataka. Both are recognised classical languages (Kannada 2008, Malayalam 2013).","e":"Telugu was recognised along with Kannada in 2008.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0094","q":"In which year was Sanskrit declared a classical language of India?","o":["1976","1950","1999","2005"],"a":3,"x":"Sanskrit was declared a classical language in 2005, the second after Tamil (2004).","e":"Order: Tamil 2004, Sanskrit 2005, Telugu and Kannada 2008, Malayalam 2013, Odia 2014; Marathi, Pali, Prakrit, Assamese and Bengali in 2024.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0190","q":"Which of the following is true about the National Independence Day celebrations in India?","o":["It marks the date of adoption of the Indian Constitution.","It is celebrated on 15 August to mark the signing of the Treaty of Versailles.","It celebrates India's victory in the 1965 war with Pakistan.","The Prime Minister unfurls the national flag at Red Fort every year."],"a":3,"x":"On Independence Day (15 August) the Prime Minister hoists the national flag at the Red Fort, Delhi, and addresses the nation.","e":"On Republic Day the President unfurls the flag at Kartavya Path.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0238","q":"What is one of the key criterion for a language to be declared a Classical Language?","o":["It must not have a history of more than 500 years.","It must have a body of ancient literature and texts.","It must be widely spoken in multiple regions.","It must be taught in all educational institutions."],"a":1,"x":"A classical language must have ancient texts or recorded history over 1,500–2,000 years, a body of valued ancient literature, and a literary tradition of its own.","e":"India now has 11 classical languages.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0268","q":"In which of the following states of India, the World War II Cemetery, which was found to have around 1000 graves at the time of its discovery in 1997, is located?","o":["Andhra Pradesh","Gujarat","Goa","Arunachal Pradesh"],"a":3,"x":"The Jairampur (Pangsau Pass) World War II cemetery in Changlang district, Arunachal Pradesh, was found in 1997 with about 1,000 graves of Allied soldiers from the Stilwell Road work.","e":"The Stilwell (Ledo) Road linked Ledo in Assam to China through Myanmar.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0343","q":"In which script is the language Hindi, an offshoot of Sanskrit, traditionally written?","o":["Sinhala","Gurumukhi","Nandinagari","Devanagari"],"a":3,"x":"Hindi is written in the Devanagari script, as are Sanskrit, Marathi and Nepali.","e":"Gurmukhi is used for Punjabi; Nandinagari is an old southern variant used for Sanskrit.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0443","q":"Where is the Central Institute of Indian Languages located?","o":["Hyderabad","Mysuru","Thiruvananthapuram","Bengaluru"],"a":1,"x":"The Central Institute of Indian Languages (CIIL) is in Mysuru, Karnataka, under the Ministry of Education.","e":"It was set up in 1969.","src":["ASO 27 Aug 2025 S1"]},{"id":"q0448","q":"Which of the following is a criterion for a language to be declared as classical in India, as per the revised criteria shared by the Government of India in 2024?","o":["The language must have a recorded history spanning at least 500 years.","The language must be spoken by at least 10 million people.","The language should have a body of ancient literature considered a valuable heritage by generations of speakers.","The language should have originated from Sanskrit."],"a":2,"x":"Under the revised criteria (2024), a classical language needs a recorded history of 1,500–2,000 years, ancient literature valued as heritage, and knowledge texts (prose, inscriptions).","e":"Marathi, Pali, Prakrit, Assamese and Bengali were added in October 2024.","src":["ASO 27 Aug 2025 S1"]},{"id":"q0449","q":"The Human Development Report is released by UNDP. The headquarter of UNDP is located at which of the following places?","o":["New York, USA","Paris, France","Geneva, Switzerland","Basel, Switzerland"],"a":0,"x":"UNDP is headquartered in New York and publishes the Human Development Report every year.","e":"UNESCO: Paris. WHO: Geneva. World Bank: Washington DC.","src":["ASO 27 Aug 2025 S1"]},{"id":"q0480","q":"In which year was the Central Institute of Indian Languages at Mysore set up, to help in evolving and implementing the language policy of the Government of India?","o":["1971","1965","1969","1967"],"a":2,"x":"The Central Institute of Indian Languages was set up at Mysore on 17 July 1969 to help develop and implement India's language policy.","e":"It works under the Ministry of Education.","src":["ASO 27 Aug 2025 S1"]},{"id":"q1591","q":"The Lalit Kala Akademi was inaugurated in New Delhi in the year _____.","o":["1953","1954","1952","1951"],"a":1,"x":"The Lalit Kala Akademi (National Academy of Art) was inaugurated in New Delhi in 1954.","e":"Sangeet Natak Akademi and Sahitya Akademi were also set up in the early 1950s.","src":["Patwari 20 Aug 2022 S2"]},{"id":"q1612","q":"Which Prime Minister declared India a full-fledged nuclear weapon state?","o":["Narendra Modi","Indira Gandhi","Atal Bihari Vajpayee","Manmohan Singh"],"a":2,"x":"After the Pokhran-II tests in May 1998, Prime Minister Atal Bihari Vajpayee declared India a nuclear weapon state.","e":"The tests were code-named Operation Shakti; 11 May is National Technology Day.","src":["Patwari 17 Sep 2022 S3"]},{"id":"q0504","q":"Chandrayaan-1 was India's first lunar probe. It was launched under the chairmanship of __________.","o":["Krishnaswamy Kasturirangan","K. Radhakrishnan","A. S. Kiran Kumar","G. Madhavan Nair"],"a":3,"x":"Chandrayaan-1 was launched on 22 October 2008 from Sriharikota when G. Madhavan Nair was ISRO chairman; its instruments helped confirm water on the Moon.","e":"Chandrayaan-3 landed near the lunar south pole on 23 August 2023, now National Space Day.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0506","q":"Malala Yousafzai received the Nobel Prize for Peace at the age of _______.","o":["20","17","22","19"],"a":1,"x":"Malala Yousafzai won the Nobel Peace Prize in 2014 at 17, the youngest Nobel laureate; she shared it with India's Kailash Satyarthi.","e":"Both campaigned for children's rights and education.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0507","q":"Subrahmanyam Chandrasekhar received the Nobel Prize in 1983 for his contribution in the field of __________.","o":["physics","literature","chemistry","peace"],"a":0,"x":"Subrahmanyan Chandrasekhar won the 1983 Nobel Prize in Physics for work on the structure and evolution of stars; the Chandrasekhar limit is named after him.","e":"C. V. Raman, his uncle, won Physics in 1930 for the Raman effect.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0544","q":"Which among the following awards are famously known as 'Oscars'?","o":["Academy Awards","Grammy Awards","Emmy Awards","Golden Globe Awards"],"a":0,"x":"The Oscars are the Academy Awards, given since 1929 by the Academy of Motion Picture Arts and Sciences, USA.","e":"Grammy: music. Emmy: television.","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0545","q":"Who among the following was known as the \"Young Turk\"?","o":["Jawaharlal Nehru","Ashutosh Mukherji","Chandra Shekhar","Bal Gangadhar Tilak"],"a":2,"x":"Chandra Shekhar, later Prime Minister (1990–91), was called the 'Young Turk' for leading a group of young radical Congress leaders in the late 1960s and 1970s.","e":"He was the first PM who had never held a minister's post before.","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0584","q":"Who among the following didn't receive the Bharat Ratna award in 2019?","o":["Bhupen Hazarika","Nanaji Deshmukh","Pranab Mukherjee","Virat Kohli"],"a":3,"x":"Bharat Ratna 2019 went to Pranab Mukherjee, Nanaji Deshmukh (posthumous) and Bhupen Hazarika (posthumous). Virat Kohli was not a recipient.","e":"Sachin Tendulkar (2014) is the only sportsperson to get the Bharat Ratna.","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0586","q":"Where is the headquarters of the Association of Southeast Asian Nations located?","o":["China","Indonesia","Nepal","Vietnam"],"a":1,"x":"ASEAN's secretariat is in Jakarta, Indonesia; ASEAN was founded in 1967 by the Bangkok Declaration.","e":"Timor-Leste became its 11th member in 2025.","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0588","q":"Every year, the state of Odisha celebrates Utkal Divas on __________.","o":["1st April","31st march","2nd April","29th March"],"a":0,"x":"Odisha celebrates Utkal Divas (Odisha Day) on 1 April, marking its formation as a separate province in 1936.","e":"It was the first province formed on a linguistic basis in British India.","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0624","q":"Which among the following countries is not a member of the Group of Eight (G8)?","o":["United States","Japan","United Kingdom","India"],"a":3,"x":"India is not a member of the G8 (USA, UK, France, Germany, Italy, Japan, Canada, Russia); it became the G7 after Russia's suspension in 2014.","e":"India is a member of the G20 and hosted its 2023 summit.","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0626","q":"Kalinga Prize is an award given by UNESCO for the contribution in the field of ____________.","o":["literature","science","peace","architecture"],"a":1,"x":"UNESCO's Kalinga Prize (from 1952, funded by Biju Patnaik) honours popularisation of science.","e":"The first winner was Louis de Broglie.","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0627","q":"Which among the following was India's first experimental satellite launch vehicle?","o":["SLV-4","SLV-1","SLV-3","SLV-2"],"a":2,"x":"SLV-3 was India's first experimental satellite launch vehicle; it put the Rohini satellite into orbit in July 1980 under project director Dr A. P. J. Abdul Kalam.","e":"Later vehicles: ASLV, PSLV, GSLV, LVM3.","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0664","q":"Wangari Maathai is the first African woman to be awarded the Nobel Prize for her contribution in the field of __________.","o":["chemistry","physics","literature","peace"],"a":3,"x":"Wangari Maathai of Kenya won the 2004 Nobel Peace Prize, the first African woman Nobel laureate, for sustainable development and her Green Belt Movement.","e":"Her movement planted over 30 million trees.","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0666","q":"Who among the following gave the slogan \"Jai Jawan Jai Kisan\"?","o":["Subhash Chandra Bose","Jawaharlal Nehru","Lal Bahadur Shastri","Mahatma Gandhi"],"a":2,"x":"Lal Bahadur Shastri gave the slogan 'Jai Jawan Jai Kisan' in 1965, during the war with Pakistan and food shortages.","e":"Atal Bihari Vajpayee added 'Jai Vigyan' in 1998.","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0667","q":"Which among the following was replaced by the World Trade Organisation?","o":["General Agreement on Tariffs and Trade","International Monetary Fund","Trade-Related Investment Measures","Trade-Related Intellectual Property Rights"],"a":0,"x":"The World Trade Organization (1 January 1995, Geneva) replaced the General Agreement on Tariffs and Trade (GATT, 1947), following the Uruguay Round.","e":"India is a founder member of both GATT and the WTO.","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0704","q":"For which of the following films did Bhanu Athaiya receive an oscar for the best costume designer?","o":["Swades","Lagaan: Once Upon a Time in India","Gandhi","Slumdog Millionaire"],"a":2,"x":"Bhanu Athaiya won the Oscar for Best Costume Design for 'Gandhi' (1982), the first Indian to win an Academy Award.","e":"A. R. Rahman and Resul Pookutty won for 'Slumdog Millionaire' (2009).","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0706","q":"Who among the following was the first chairman of the ISRO?","o":["Satish Dhawan","Vikram Sarabhai","Shailesh Nayak","A. S. Kiran Kumar"],"a":1,"x":"Dr Vikram Sarabhai, father of India's space programme, was ISRO's first chairman (1969).","e":"ISRO grew out of INCOSPAR (1962).","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0707","q":"Where was the first session of United Nations held?","o":["London","Paris","Geneva","New York"],"a":0,"x":"The first session of the UN General Assembly opened in London (Methodist Central Hall) on 10 January 1946.","e":"The UN Charter was signed at San Francisco in June 1945; UN Day is 24 October.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0744","q":"Amongst the following, who created the \"You Said It\" comic strip featured in the The Times of India?","o":["Satish Acharya","R.K. Laxman","Sudhir Tailang","Abu Abraham"],"a":1,"x":"R. K. Laxman created the 'You Said It' cartoon strip with 'The Common Man' in The Times of India from 1951.","e":"His brother R. K. Narayan wrote 'Malgudi Days'.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q0745","q":"Amongst the following, name India's highest military honour for distinguished valour during wartime.","o":["Param Vir Chakra","Ashok Chakra","Kirti Chakra","Maha Vir Chakra"],"a":0,"x":"The Param Vir Chakra is India's highest military award for the highest gallantry in the presence of the enemy.","e":"The Ashoka Chakra is the highest peacetime gallantry award.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q0747","q":"What was the code name for India's first nuclear test conducted at Pokhran in 1974?","o":["Operation Shakti","Peaceful Buddha","Operation Bandar","Smiling Buddha"],"a":3,"x":"India's first nuclear test at Pokhran on 18 May 1974 was code-named 'Smiling Buddha'.","e":"The 1998 tests were 'Operation Shakti'.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q1314","q":"Who out of the following had served as the first Indian Commander-in-Chief of the Indian Army?","o":["General Sam Manekshaw","General Arjan Singh","General K.M. Cariappa","General Maharaj Rajendra Sinhji"],"a":2,"x":"General K. M. Cariappa became the first Indian Commander-in-Chief of the Indian Army on 15 January 1949, marked as Army Day.","e":"Cariappa and Sam Manekshaw are the only two Field Marshals of the Indian Army.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1318","q":"On which of the following days is the Padma Awards announced?","o":["On Shaheed Diwas","On the eve of the Republic Day","On the Independence Day","On the eve of the Independence Day"],"a":1,"x":"The Padma Awards (Padma Vibhushan, Padma Bhushan, Padma Shri) are announced on the eve of Republic Day each year.","e":"They were instituted in 1954.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1319","q":"Which of the following days was observed as the Women's Day in 2020?","o":["March 8th","March 5th","March 6th","March 7th"],"a":0,"x":"International Women's Day is observed on 8 March every year.","e":"National Women's Day in India is 13 February, Sarojini Naidu's birthday.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1356","q":"The Pritzker Prize is awarded for the achievement in the field of _______________.","o":["literature","music","mathematics","architecture"],"a":3,"x":"The Pritzker Architecture Prize is often called architecture's Nobel. B. V. Doshi (2018) was the first Indian winner.","e":"Balkrishna Doshi designed IIM Bangalore.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1038","q":"The Automatic Train Protection (ATP) system, KAVACH, was indigenously developed by which of the following agencies to help Indian Railways achieve zero accidents?","o":["Research Designs and Standards Organisation (RDSO)","Bharat Electronics Limited (BEL)","Bharat Heavy Electricals Limited (BHEL)","Integral Coach Factory (ICF)"],"a":0,"x":"Kavach, India's automatic train protection system, was developed by the Research Designs and Standards Organisation (RDSO), Lucknow, with Indian industry.","e":"It applies brakes automatically if the driver misses a signal.","src":["PRT 20 Feb 2026 S1"]},{"id":"q1263","q":"The World Energy Outlook 2025 was released by which organisation?","o":["International Monetary Fund","International Energy Agency","Organization Petroleum Energy Agency","World Meteorological Organization of Energy"],"a":1,"x":"The World Energy Outlook is published every year by the International Energy Agency (IEA), headquartered in Paris.","e":"OPEC, based in Vienna, publishes the World Oil Outlook.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1386","q":"Where is the India’s first Dark Night Sky Reserve being established?","o":["Ladakh","Daman and Diu","Lakshadweep","Dadra and Nagar Haveli"],"a":0,"x":"India's first Dark Sky Reserve is at Hanle in Ladakh, set up in 2022 around the Indian Astronomical Observatory.","e":"Hanle's observatory is among the world's highest.","src":["TGT 24 Jun 2023 S3"]},{"id":"q1396","q":"What name was given to the operation for liberation of Goa, in 1961, to make it a part of the Union of India?","o":["Operation Vijay","Operation Margao","Operation Polo","Operation Searchlight"],"a":0,"x":"Operation Vijay (December 1961) liberated Goa, Daman and Diu from Portuguese rule; 19 December is Goa Liberation Day.","e":"Operation Polo (1948) integrated Hyderabad.","src":["TGT 24 Jun 2023 S3"]},{"id":"q1415","q":"Which of the following man-made objects was the first one to cross the heliosphere of our solar system?","o":["Sputnik-1","New Horizons","Messenger-1","Voyager-1"],"a":3,"x":"Voyager 1 (launched 1977) became the first human-made object to cross the heliosphere into interstellar space, in August 2012.","e":"Voyager 2 crossed in 2018.","src":["TGT 25 Jun 2023 S1"]},{"id":"q1455","q":"What is the angle of inclination of the International Space Station’s orbit compared to the equator?","o":["66.8 degrees","0 degrees","51.6 degrees","22.5 degrees"],"a":2,"x":"The International Space Station orbits at an inclination of about 51.6° to the equator, at around 400 km altitude.","e":"It circles Earth about every 90 minutes.","src":["TGT 25 Jun 2023 S3"]},{"id":"q1484","q":"On which date is the International Day of Non-Violence observed?","o":["2 November","2 December","2 January","2 October"],"a":3,"x":"The UN observes the International Day of Non-Violence on 2 October, Gandhi's birthday (adopted 2007).","e":"In India, 2 October is Gandhi Jayanti, a national holiday.","src":["TGT 29 Aug 2025"]},{"id":"q1488","q":"Good Governance Day (25 December) commemorates the birth anniversary of which former Prime Minister?","o":["Inder Kumar Gujral","Haradanahalli Doddegowda Deve Gowda","Atal Bihari Vajpayee","Vishwanath Pratap Singh"],"a":2,"x":"Good Governance Day is observed on 25 December, the birth anniversary of former Prime Minister Atal Bihari Vajpayee.","e":"Vajpayee received the Bharat Ratna in 2015.","src":["TGT 29 Aug 2025"]},{"id":"q1489","q":"In which year was Odia given Classical Language status?","o":["2011","2015","2012","2014"],"a":3,"x":"Odia was declared a classical language in 2014, the sixth after Tamil, Sanskrit, Telugu, Kannada and Malayalam.","e":"It was the first Indo-Aryan language after Sanskrit to get the status.","src":["TGT 29 Aug 2025"]},{"id":"q1495","q":"Indian Air Force approved the production of Astra Mark-1(MK-1) missile. Which of the following types of missile is Astra Mark-1?","o":["Air to Air","Surface to Air","Surface to Surface","Air to Surface"],"a":0,"x":"Astra Mk-1 is an indigenous beyond-visual-range air-to-air missile developed by DRDO for the Indian Air Force.","e":"Akash is surface-to-air; BrahMos is a supersonic cruise missile.","src":["TGT 29 Aug 2025"]},{"id":"q1512","q":"In which of the following cities is the headquarters of the Central Institute of Hindi (Kendriya Hindi Sansthan) located?","o":["Agra","Jalandhar","Mumbai","Patna"],"a":0,"x":"The Kendriya Hindi Sansthan (Central Institute of Hindi) has its headquarters in Agra, Uttar Pradesh.","e":"It trains teachers of Hindi as a second or foreign language.","src":["TGT 24 Aug 2025 S1"]},{"id":"q1555","q":"The Indian Space Research Organisation (ISRO) was formed in August ________.","o":["1969","1960","1976","1955"],"a":0,"x":"ISRO was formed on 15 August 1969, replacing INCOSPAR; its headquarters is in Bengaluru.","e":"India's first satellite, Aryabhata, was launched in 1975 on a Soviet rocket.","src":["TGT 31 Aug 2025 S1"]},{"id":"q1563","q":"The Kendriya Hindi Sansthan was established in the year _________ under the Ministry of Human Resources Development (Ministry of Education).","o":["1965","1954","1951","1961"],"a":3,"x":"The Kendriya Hindi Sansthan was set up in 1961 under the Ministry of Education (then HRD), with its headquarters at Agra.","e":"The Central Hindi Directorate was set up in 1960.","src":["TGT 31 Aug 2025 S1"]},{"id":"q0770","q":"Which language was the first to get classical language status in India, in 2004?","o":["Sanskrit","Kannada","Tamil","Telugu"],"a":2,"x":"Tamil was the first language declared classical in India, in 2004.","e":"Sanskrit followed in 2005.","src":["PGT 25 Sep 2025"]},{"id":"q0799","q":"The Sandalwood film industry is associated with which language?","o":["Kannada","Telugu","Malayalam","Tamil"],"a":0,"x":"'Sandalwood' is the nickname of the Kannada film industry, based in Bengaluru.","e":"Tollywood: Telugu. Kollywood: Tamil. Mollywood: Malayalam.","src":["PGT 11 Jul 2025 S1"]},{"id":"q0841","q":"Which of the following is NOT a national festival of India?","o":["Gandhi Jayanti","Constitution Day","Republic Day","Independence Day"],"a":1,"x":"India's three national festivals are Republic Day (26 January), Independence Day (15 August) and Gandhi Jayanti (2 October). Constitution Day (26 November) is observed but is not a national festival.","e":"Constitution Day has been observed since 2015.","src":["PGT 14 Jul 2025"]},{"id":"q0842","q":"In which of the following cities of India is the headquarters of National Council for Promotion of Urdu Language located?","o":["Agra","Mumbai","New Delhi","Hyderabad"],"a":2,"x":"The National Council for Promotion of Urdu Language is headquartered in New Delhi, under the Ministry of Education.","e":"It started work in 1996.","src":["PGT 14 Jul 2025"]},{"id":"q0851","q":"In which of the following years did the National Council for Promotion of Urdu Language start its operations?","o":["1996","1997","1999","1998"],"a":0,"x":"The National Council for Promotion of Urdu Language began operating in 1996, in New Delhi.","e":"Urdu is one of the 22 languages in the Eighth Schedule.","src":["PGT 14 Jul 2025"]},{"id":"q0876","q":"On which date is National Broadcasting Day observed in India every year?","o":["15 August","22 July","1 August","23 July"],"a":3,"x":"National Broadcasting Day is observed on 23 July: on that day in 1927 the Indian Broadcasting Company began regular radio broadcasts from Bombay.","e":"The Indian State Broadcasting Service became All India Radio in 1936.","src":["PGT 24 Sep 2025"]}]}]});
